public class CustomUserDetails implements UserDetails {
    private final User user;

    public CustomUserDetails(User user) {
        this.user = user;
    }

    @Override
    public String getUsername() {
        return user.getEmail(); // using email as username
    }

    @Override
    public String getPassword() {
        return user.getPasswordHash(); // BCrypt encoded
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return user.getRoles().stream()
            .map(role -> new SimpleGrantedAuthority("ROLE_" + role))
            .toList();
    }

    @Override
    public boolean isEnabled() {
        return user.isActive();
    }

    @Override
    public boolean isAccountNonLocked() {
        return !user.isLocked();
    }

    @Override
    public boolean isAccountNonExpired() {
        return true; // implement if you have expiration logic
    }

    @Override
    public boolean isCredentialsNonExpired() {
        return true; // implement for password expiration
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
            .requestMatchers("/api/public/**").permitAll()
            .requestMatchers("/api/admin/**").hasRole("ADMIN") // checks ROLE_ADMIN
            .requestMatchers("/api/orders/**").hasAnyRole("USER", "ADMIN")
            .requestMatchers("/api/reports/**").hasAuthority("ROLE_MANAGER") // exact match
            .anyRequest().authenticated()
        );
        return http.build();
    }
}

