@Service
public class OrderService {
    private final OrderRepository orderRepository;

    public List<Order> getCurrentUserOrders() {
        var authentication = SecurityContextHolder.getContext().getAuthentication();

        if (authentication == null || !authentication.isAuthenticated()) {
            throw new UnauthorizedException("No authenticated user");
        }

        var userDetails = (CustomUserDetails) authentication.getPrincipal();
        var userId = userDetails.getUser().getId();

        return orderRepository.findByUserId(userId);
    }

    public boolean isAdmin() {
        var authentication = SecurityContextHolder.getContext().getAuthentication();
        return authentication.getAuthorities().stream()
            .anyMatch(auth -> auth.getAuthority().equals("ROLE_ADMIN"));
    }

    public String getCurrentUsername() {
        return SecurityContextHolder.getContext()
            .getAuthentication()
            .getName(); // returns username from principal
    }
}

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {
    private final JwtTokenProvider jwtTokenProvider;
    private final UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                    HttpServletResponse response, 
                                    FilterChain filterChain) throws ServletException, IOException {
        var token = extractTokenFromHeader(request);

        if (token != null && jwtTokenProvider.validateToken(token)) {
            var username = jwtTokenProvider.getUsernameFromToken(token);
            var userDetails = userDetailsService.loadUserByUsername(username);

            var authentication = new UsernamePasswordAuthenticationToken(
                userDetails, null, userDetails.getAuthorities());

            SecurityContextHolder.getContext().setAuthentication(authentication);
        }

        filterChain.doFilter(request, response); // pass to next filter
    }

    private String extractTokenFromHeader(HttpServletRequest request) {
        var header = request.getHeader("Authorization");
        return (header != null && header.startsWith("Bearer ")) 
            ? header.substring(7) : null;
    }
}

@Configuration
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12); // work factor 12 (default is 10)
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
            .formLogin(Customizer.withDefaults());
        return http.build();
    }
}

@Service
public class UserService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    public void registerUser(String email, String rawPassword) {
        var encodedPassword = passwordEncoder.encode(rawPassword);
        var user = new User(email, encodedPassword, Set.of("USER"));
        userRepository.save(user); // stores BCrypt hash like $2a$12$...
    }

    public boolean verifyPassword(String rawPassword, String storedHash) {
        return passwordEncoder.matches(rawPassword, storedHash);
    }
}
